-- Errata reading for N10: Age = latest reported age (most recent demographic_updates age_reported received by the as-of date, else the roster age_reported); everything else as the reference.
WITH r AS MATERIALIZED (SELECT patient, payload FROM records WHERE stream='conditions') SELECT COUNT(DISTINCT r.patient) AS count FROM r JOIN patients p ON p.id=r.patient WHERE coalesce((SELECT json_extract(du_.payload,'$.age_reported') FROM records du_ WHERE du_.stream='demographic_updates' AND du_.patient=p.id AND json_extract(du_.payload,'$.age_reported') IS NOT NULL ORDER BY json_extract(du_.payload,'$.age_reference_date') DESC LIMIT 1), json_extract(p.payload,'$.age_reported')) < 18 AND (lower(coalesce(json_extract(r.payload,'$.description'),'')) LIKE '%asthma%' OR coalesce(json_extract(r.payload,'$.icd10'),'') LIKE 'J45%');
